+package main
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"strings"
+)
+
+const Version = "v1.13.0"
+
+type FileEntry struct {
+	Name    string
+	Path    string
+	IsDir   bool
+	IsHidden bool
+}
+
+type State struct {
+	CurrentPath string
+	Files       []FileEntry
+	OriginalFiles []FileEntry
+	PreviewMode bool
+	PreviewFile string
+	PreviewContent string
+	PreviewWithBorder bool
+	ShowIcons bool
+	DirOnly bool
+	HideHidden bool
+	FuzzyMode bool
+	SearchQuery string
+	SearchResults []FileEntry
+	SearchIndex int
+	SelectedIndex int
+	OriginalIndex int
+	Clipboard string
+	ShowHelp bool
+}
+
+func main() {
+	if len(os.Args) > 1 {
+		if os.Args[1] == "--help" || os.Args[1] == "-h" {
+			printHelp()
+			os.Exit(0)
+		}
+		if os.Args[1] == "--version" || os.Args[1] == "-v" {
+			fmt.Println(Version)
+			os.Exit(0)
+		}
+	}
+
+	// Check for TTY
+	if !hasTTY() {
+		fmt.Fprintln(os.Stderr, "walk: requires a terminal")
+		os.Exit(1)
+	}
+
+	state := initState()
+	
+	// Parse flags
+	for i := 1; i < len(os.Args); i++ {
+		switch os.Args[i] {
+		case "--icons":
+			state.ShowIcons = true
+		case "--dir-only":
+			state.DirOnly = true
+		case "--hide-hidden":
+			state.HideHidden = true
+		case "--preview":
+			state.PreviewMode = true
+		case "--with-border":
+			state.PreviewWithBorder = true
+		case "--fuzzy":
+			state.FuzzyMode = true
+		}
+	}
+
+	// Get initial path
+	if len(os.Args) > 2 {
+		state.CurrentPath = os.Args[2]
+	} else {
+		state.CurrentPath = "."
+	}
+
+	// Load files
+	state.OriginalFiles = loadFiles(state.CurrentPath, state.HideHidden, state.DirOnly)
+	state.Files = make([]FileEntry, len(state.OriginalFiles))
+	copy(state.Files, state.OriginalFiles)
+	state.OriginalIndex = 0
+
+	// Main loop
+	for {
+		state.render()
+		key := readKey()
+		state.handleKey(key)
+	}
+}
+
+func hasTTY() bool {
+	return os.Getenv("TERM") != ""
+}
+
+func initState() *State {
+	return &State{
+		CurrentPath: ".",
+		Files:       []FileEntry{},
+		PreviewMode: false,
+		PreviewWithBorder: false,
+		ShowIcons: false,
+		DirOnly: false,
+		HideHidden: false,
+		FuzzyMode: false,
+		SelectedIndex: 0,
+		Clipboard: "",
+	}
+}
+
+func loadFiles(path string, hideHidden, dirOnly bool) []FileEntry {
+	entries, err := os.ReadDir(path)
+	if err != nil {
+		return []FileEntry{}
+	}
+
+	var files []FileEntry
+	for _, entry := range entries {
+		if entry.IsDir() {
+			files = append(files, FileEntry{
+				Name:    entry.Name(),
+				Path:    filepath.Join(path, entry.Name()),
+				IsDir:   true,
+				IsHidden: strings.HasPrefix(entry.Name(), "."),
+			})
+		} else {
+			files = append(files, FileEntry{
+				Name:    entry.Name(),
+				Path:    filepath.Join(path, entry.Name()),
+				IsDir:   false,
+				IsHidden: strings.HasPrefix(entry.Name(), "."),
+			})
+		}
+	}
+
+	if hideHidden {
+		var filtered []FileEntry
+		for _, f := range files {
+			if !f.IsHidden {
+				filtered = append(filtered, f)
+			}
+		}
+		files = filtered
+	}
+
+	if dirOnly {
+		var filtered []FileEntry
+		for _, f := range files {
+			if f.IsDir {
+				filtered = append(filtered, f)
+			}
+		}
+		files = filtered
+	}
+
+	return files
+}
+
+func (s *State) render() {
+	// Clear screen
+	fmt.Print("\033[2J\033[H")
+
+	// Show help if requested
+	if s.ShowHelp {
+		printHelp()
+		s.ShowHelp = false
+		return
+	}
+
+	// Show preview if in preview mode
+	if s.PreviewMode {
+		s.renderPreview()
+	}
+
+	// Show file list
+	s.renderFileList()
+}
+
+func (s *State) renderPreview() {
+	if s.PreviewFile == "" {
+		return
+	}
+
+	if s.PreviewWithBorder {
+		fmt.Println("┌─────────────────────────────────────────────────────────────┐")
+		fmt.Println("│  Preview                                                    │")
+		fmt.Println("├─────────────────────────────────────────────────────────────┤")
+	} else {
+		fmt.Println("Preview:")
+	}
+
+	content := s.PreviewContent
+	if content == "" {
+		content = "No preview available"
+	}
+
+	// Truncate if too long
+	if len(content) > 80 {
+		content = content[:80] + "..."
+	}
+
+	fmt.Println(content)
+
+	if s.PreviewWithBorder {
+		fmt.Println("└─────────────────────────────────────────────────────────────┘")
+	}
+}
+
+func (s *State) renderFileList() {
+	fmt.Println("Files:")
+
+	if len(s.Files) == 0 {
+		fmt.Println("  (empty)")
+		return
+	}
+
+	for i, file := range s.Files {
+		prefix := "  "
+		if i == s.SelectedIndex {
+			prefix = "➜ "
+		}
+		fmt.Printf("%s%s\n", prefix, file.Name)
+	}
+}
+
+func (s *State) handleKey(key rune) {
+	switch key {
+	case '\n':
+		if s.SelectedIndex < len(s.Files) {
+			s.enterDirectory(s.Files[s.SelectedIndex].Path)
+		}
+	case '\r':
+		if s.SelectedIndex < len(s.Files) {
+			s.enterDirectory(s.Files[s.SelectedIndex].Path)
+		}
+	case 27: // ESC
+		s.exitWithCD()
+	case 'q':
+		s.exitWithCD()
+	case 'h', 'j', 'k', 'l':
+		s.moveSelection(key)
+	case ' ':
+		s.togglePreview()
+	case '/':
+		s.startSearch()
